export * as Popover from './popover.tsx';
export type {
  CloseOwnProps as PopoverCloseOwnProps,
  CloseProps as PopoverCloseProps,
  ContentOwnProps as PopoverContentOwnProps,
  ContentProps as PopoverContentProps,
  PlacementProps as PopoverPlacementProps,
} from './popover.tsx';

@layer hj.components {
  /* Customise: --hj-popover-width · --hj-popover-padding · --hj-popover-radius */
  .hj-popover-positioner {
    z-index: var(--hj-z-popover);
    outline: none;
  }
  .hj-popover-backdrop {
    position: fixed;
    inset: 0;
  }

  /* An anchored surface: surface-2, hairline, and the one declared lift. Grows from its anchor. */
  .hj-popover-popup {
    position: relative;
    display: flex;
    flex-direction: column;
    gap: calc(6px * var(--hj-density));
    width: max-content;
    max-width: min(var(--hj-popover-width, 320px), var(--available-width, 100vw));
    max-height: var(--available-height, 80vh);
    overflow: auto;
    padding: var(--hj-popover-padding, calc(16px * var(--hj-density)));
    border: 1px solid var(--hj-line);
    border-radius: var(--hj-popover-radius, var(--hj-radius-md));
    corner-shape: var(--hj-corner-shape, round);
    background: var(--hj-surface-2);
    box-shadow: var(--hj-shadow-lift);
    color: var(--hj-fg);
    font-family: var(--hj-font-sans);
    outline: none;
    transform-origin: var(--transform-origin);
    transition:
      transform var(--hj-dur-snappy) var(--hj-ease-snappy),
      opacity var(--hj-dur-base) var(--hj-ease-out);
  }
  .hj-popover-popup[data-starting-style],
  .hj-popover-popup[data-ending-style] {
    opacity: 0;
    transform: scale(0.92);
  }
  .hj-popover-popup[data-ending-style] {
    transition-duration: var(--hj-dur-fast);
    transition-timing-function: var(--hj-ease-out);
  }
  .hj-popover-popup[data-instant] {
    transition: none;
  }

  .hj-popover-viewport {
    position: relative;
    overflow: clip;
  }

  .hj-popover-title {
    margin: 0;
    padding-right: calc(28px * var(--hj-density));
    font: var(--hj-type-heading);
    letter-spacing: var(--hj-tracking-heading);
  }
  .hj-popover-description {
    margin: 0;
    font-size: 13.5px;
    line-height: 1.5;
    color: var(--hj-fg-dim);
  }
  .hj-popover-actions {
    display: flex;
    justify-content: flex-end;
    gap: calc(8px * var(--hj-density));
    margin-top: calc(10px * var(--hj-density));
  }

  .hj-popover-close[data-icon] {
    position: absolute;
    top: 10px;
    right: 10px;
    display: grid;
    place-items: center;
    width: 28px;
    height: 28px;
    padding: 0;
    border: 0;
    border-radius: var(--hj-radius-pill);
    background: transparent;
    color: var(--hj-fg-mute);
    font-size: 14px;
    line-height: 0;
    cursor: pointer;
    transition:
      background-color var(--hj-dur-fast) var(--hj-ease-out),
      color var(--hj-dur-fast) var(--hj-ease-out),
      transform var(--hj-dur-snappy) var(--hj-ease-snappy);
  }
  .hj-popover-close[data-icon]::before {
    content: '';
    position: absolute;
    inset: -8px;
  }
  .hj-popover-close[data-icon]:hover {
    background: color-mix(in srgb, var(--hj-fg) 8%, transparent);
    color: var(--hj-fg);
  }
  .hj-popover-close[data-icon]:active {
    transform: scale(0.92);
    transition-duration: 70ms;
  }
  .hj-popover-close[data-icon] svg {
    width: 14px;
    height: 14px;
  }

  /* The arrow: a rotated square with the popup's paint, clipped to a triangle. */
  .hj-popover-arrow {
    position: relative;
    display: block;
    width: 14px;
    height: 7px;
    overflow: clip;
  }
  .hj-popover-arrow[data-side='top'] {
    bottom: -7px;
    rotate: 180deg;
  }
  .hj-popover-arrow[data-side='bottom'] {
    top: -7px;
  }
  .hj-popover-arrow[data-side='left'] {
    right: -10px;
    rotate: 90deg;
  }
  .hj-popover-arrow[data-side='right'] {
    left: -10px;
    rotate: -90deg;
  }
  .hj-popover-arrow::before {
    content: '';
    position: absolute;
    bottom: 0;
    left: 50%;
    width: 10px;
    height: 10px;
    border: 1px solid var(--hj-line);
    background: var(--hj-surface-2);
    transform: translate(-50%, 50%) rotate(45deg);
  }
}

'use client';
import { Popover as Base } from '@base-ui/react/popover';
import * as React from 'react';

import { useHanjiConfig } from '../../system/config.tsx';
import { elementPart, part } from '../../system/part.tsx';
import type { ElementPartProps, HanjiPart } from '../../system/part.tsx';
import { cls, flag, withDefaults } from '../../system/slot.ts';
import { ThemeScope } from '../../system/theme.tsx';

export const Root: typeof Base.Root = Base.Root;
export const Trigger: HanjiPart<typeof Base.Trigger> = part(
  Base.Trigger,
  'Popover.Trigger',
  'hj-popover-trigger',
);
export const Backdrop: HanjiPart<typeof Base.Backdrop> = part(
  Base.Backdrop,
  'Popover.Backdrop',
  'hj-popover-backdrop',
);
export const Positioner: HanjiPart<typeof Base.Positioner> = part(
  Base.Positioner,
  'Popover.Positioner',
  'hj-popover-positioner',
);
export const Popup: HanjiPart<typeof Base.Popup> = part(
  Base.Popup,
  'Popover.Popup',
  'hj-popover-popup',
);
export const Arrow: HanjiPart<typeof Base.Arrow> = part(
  Base.Arrow,
  'Popover.Arrow',
  'hj-popover-arrow',
);
export const Viewport: HanjiPart<typeof Base.Viewport> = part(
  Base.Viewport,
  'Popover.Viewport',
  'hj-popover-viewport',
);
export const Title: HanjiPart<typeof Base.Title> = part(
  Base.Title,
  'Popover.Title',
  'hj-popover-title',
);
export const Description: HanjiPart<typeof Base.Description> = part(
  Base.Description,
  'Popover.Description',
  'hj-popover-description',
);
/** Footer row for a popover that asks something (a small form, a confirm). */
export const Actions: (props: ElementPartProps<'div'>) => React.ReactElement = elementPart(
  'div',
  'Popover.Actions',
  'hj-popover-actions',
);
export const createHandle: typeof Base.createHandle = Base.createHandle;

/** Portals to `<body>` but keeps the nearest `<Theme>`. */
export function Portal({ children, ...props }: Base.Portal.Props): React.ReactElement {
  return (
    <Base.Portal {...props}>
      <ThemeScope>{children}</ThemeScope>
    </Base.Portal>
  );
}

export interface CloseOwnProps {
  /** Render the corner ✕ icon button. Defaults to true when the Close has no children. */
  icon?: boolean;
}
export interface CloseProps extends CloseOwnProps, Base.Close.Props {}

/** Closes the popover. With no children it renders the corner ✕ with an accessible label. */
export function Close(props: CloseProps): React.ReactElement {
  const config = useHanjiConfig();
  const { icon, className, children, ...rest } = withDefaults(config, 'Popover.Close', props);
  const asIcon = icon ?? children === undefined;
  return (
    <Base.Close
      aria-label={asIcon ? config.strings.close : undefined}
      {...rest}
      data-icon={flag(asIcon)}
      className={cls(config, 'Popover.Close', 'hj-popover-close', className)}
    >
      {asIcon ? config.icons.x : children}
    </Base.Close>
  );
}

/** Placement for the shorthand Content parts. */
export interface PlacementProps {
  /** Which side of the anchor to open on. */
  side?: Base.Positioner.Props['side'];
  align?: Base.Positioner.Props['align'];
  /** Gap from the anchor in px. @default 6 (hanji menu gap) */
  sideOffset?: Base.Positioner.Props['sideOffset'];
  alignOffset?: Base.Positioner.Props['alignOffset'];
  /** Keep this far from the viewport edge in px. @default 8 */
  collisionPadding?: Base.Positioner.Props['collisionPadding'];
}

export interface ContentOwnProps extends PlacementProps {
  /** Draw the arrow pointing at the anchor. @default false */
  arrow?: boolean;
  /** Where to portal. Defaults to `<body>`. */
  container?: Base.Portal.Props['container'];
  keepMounted?: boolean;
}
export interface ContentProps extends ContentOwnProps, Base.Popup.Props {}

/** Shorthand for Portal + Positioner + Popup (+ Arrow) — the common case in one part. */
export function Content(props: ContentProps): React.ReactElement {
  const config = useHanjiConfig();
  const {
    side,
    align,
    sideOffset = 6,
    alignOffset,
    collisionPadding = 8,
    arrow = false,
    container,
    keepMounted,
    children,
    ...popup
  } = withDefaults(config, 'Popover.Content', props);
  return (
    <Portal container={container} keepMounted={keepMounted}>
      <Positioner
        side={side}
        align={align}
        sideOffset={arrow && typeof sideOffset === 'number' ? Math.max(sideOffset, 10) : sideOffset}
        alignOffset={alignOffset}
        collisionPadding={collisionPadding}
      >
        <Popup {...popup}>
          {arrow ? <Arrow /> : null}
          {children}
        </Popup>
      </Positioner>
    </Portal>
  );
}
